// 시험 전용 mock handoff. 실제 Jira를 호출하지 않는다. 질문 내용 표식으로 실패를 재현한다.
const r = $json.body;
if (r.kind === 'lookup') {
  if (!r.enabled) return { json: { request_id: r.request_id, status: 'skipped', record: null, masked: 0 } };
  if (r.target_ticket_id !== 'T-DEMO-01') return { json: { request_id: r.request_id, status: 'denied', record: null, masked: 0 } };
  return { json: { request_id: r.request_id, status: 'ok', masked: 1, record: { ticket_id: 'T-DEMO-01', owner_id: r.actor_id, status: 'waiting_info', observed_at: 'mock', masked_phone: '010-****-0000' } } };
}
if (String(r.request_id).includes('ticket-down')) return { json: { __status: 500, error: 'mock' } };
const on = (need) => ({ status: need ? 'confirmed' : 'none' });
return { json: { request_id: r.request_id, ticket_id: r.ticket_id ?? 'T-MOCK-1', case_version: 1, state_saved: true, state_ref: { ...r.state_ref, state_revision: r.state_ref.state_revision + 1 }, recovery: null, error_code: null, effects: { created_or_reused: on(true), context_saved: on(r.action !== 'wait'), closed: on(r.action === 'close'), assigned: on(r.action === 'handoff'), alert: on(r.action === 'handoff') } } };
